const scopeIcon = { Contact: UserRound, Group: UsersRound, Submission: FileText };

function RichEditor({ value, onChange, placeholder = "Enter instructions...", minHeight }) {
  return <div className="rich-editor"><div className="rich-toolbar"><button type="button"><b>B</b></button><button type="button"><i>I</i></button><button type="button"><u>U</u></button><button type="button"><List size={18} /></button><button type="button"><ListOrdered size={18} /></button><button type="button"><AlignLeft size={18} /></button><button type="button"><AlignCenter size={18} /></button><button type="button"><AlignRight size={18} /></button><button type="button"><Link2 size={18} /></button></div><textarea style={minHeight ? { minHeight } : undefined} value={value} placeholder={placeholder} onChange={(event) => onChange?.(event.target.value)} /></div>;
}

function TypeCards({ value, onChange, includeGroups = true }) {
  const items = [{ value: "Contact", icon: UserRound, title: "Contacts", copy: "Collect contact information from people" }, ...(includeGroups ? [{ value: "Group", icon: UsersRound, title: "Groups", copy: "Collect information from sponsors and exhibitors" }] : []), { value: "Submission", icon: FileText, title: "Submissions", copy: "Collect submission-related information" }];
  return <div className="portal-type-grid">{items.map((item) => <button type="button" key={item.value} className={`portal-type-card ${value === item.value ? "selected" : ""}`} onClick={() => onChange(item.value)}><span><item.icon size={28} /></span><b>{item.title}</b><small>{item.copy}</small></button>)}</div>;
}

const blankTask = () => ({ title: "", scope: "Contact", notes: "", mode: "Manual", personIds: [], due: "" });

export function PortalTasksScreen() {
  const { data, update, persistenceStatus } = useAppStore();
  const [search, setSearch] = useState("");
  const [tab, setTab] = useState("all");
  const [addMenu, setAddMenu] = useState(false);
  const [drawer, setDrawer] = useState(false);
  const [rowMenu, setRowMenu] = useState(null);
  const [draft, setDraft] = useState(blankTask);
  const [saveError, setSaveError] = useState("");
  const counts = useMemo(() => ({
    all: data.tasks.length,
    Contact: data.tasks.filter((task) => task.scope === "Contact").length,
    Group: data.tasks.filter((task) => task.scope === "Group").length,
    Submission: data.tasks.filter((task) => task.scope === "Submission").length,
  }), [data.tasks]);
  const visible = data.tasks.filter((task) =>
    (tab === "all" || task.scope === tab) &&
    task.title.toLowerCase().includes(search.toLowerCase()),
  );
  const payloadFor = (personId) => ({
    title: draft.title,
    status: draft.complete ? "complete" : "open",
    kind: draft.scope === "Submission" ? "submission" : "contact",
    assigneePersonId: personId,
    instructions: draft.notes || null,
    dueAt: draft.due || null,
  });
  const addTask = async () => {
    setSaveError("");
    const assignees = draft.id ? [draft.personId] : draft.personIds;
    const savedTasks = [];
    let failureMessage = "";
    for (const [index, personId] of assignees.entries()) {
      let task = {
        ...draft,
        id: draft.id || `task-${Date.now()}-${index}`,
        personId,
        personIds: undefined,
        complete: draft.complete || false,
      };
      if (persistenceStatus === "d1") {
        const result = draft.id
          ? await patchSharedResource("tasks", draft.id, draft.version, payloadFor(personId))
          : await createSharedResource("tasks", payloadFor(personId));
        if (!result.ok) {
          failureMessage = result.error === "VERSION_CONFLICT"
            ? "This task changed elsewhere. Reload first."
            : savedTasks.length
              ? `${savedTasks.length} assignments were created, but the remaining assignments could not be saved.`
              : "The shared task could not be saved.";
          setSaveError(failureMessage);
          if (!savedTasks.length) return;
          break;
        }
        task = { ...task, id: result.item.id, version: result.item.version };
      }
      savedTasks.push(task);
    }
    update((state) => ({
      ...state,
      tasks: draft.id
        ? state.tasks.map((item) => item.id === draft.id ? savedTasks[0] : item)
        : [...state.tasks, ...savedTasks],
    }));
    if (!failureMessage) {
      setDrawer(false);
      setDraft(blankTask());
    }
  };
  const copyTask = () => {
    const source = data.tasks[0];
    if (!source) return;
    setDraft({ ...blankTask(), ...source, id: undefined, version: undefined, title: `${source.title} copy`, personIds: source.personId ? [source.personId] : [] });
    setDrawer(true);
    setAddMenu(false);
  };
  const removeTask = async (id) => {
    const task = data.tasks.find((item) => item.id === id);
    if (persistenceStatus === "d1") {
      const result = await deleteSharedResource("tasks", id, task?.version);
      if (!result.ok) { setSaveError("The shared task could not be deleted."); return; }
    }
    update((state) => ({ ...state, tasks: state.tasks.filter((item) => item.id !== id) }));
    setRowMenu(null);
  };
  const openNew = () => { setDraft(blankTask()); setSaveError(""); setDrawer(true); setAddMenu(false); };
  const toggleAssignee = (personId) => setDraft((current) => ({
    ...current,
    personIds: current.personIds.includes(personId)
      ? current.personIds.filter((id) => id !== personId)
      : [...current.personIds, personId],
  }));
  const selectedCount = draft.id ? Number(Boolean(draft.personId)) : draft.personIds.length;
  return <>
    <style>{PORTAL_STYLES}</style>
    <div className="portal-page">
      <PageHeader icon={CheckCircle2} title="Tasks" subtitle="Create tasks that can be assigned to your portals" actions={<SplitButton menuOpen={addMenu} onMenu={() => setAddMenu(!addMenu)} onClick={openNew} items={[{ label: "Add Task", icon: Plus, onClick: openNew }, { label: "Copy from...", icon: Copy, onClick: copyTask }]} />}/>
      {saveError ? <div className="portal-info" style={{ marginBottom: 16 }}><Info size={18}/><p>{saveError}</p></div> : null}
      <div className="portal-toolbar"><SearchBox value={search} onChange={setSearch} placeholder="Search tasks..."/></div>
      <div className="portal-tabs"><Tabs value={tab} onChange={setTab} items={[{ label: "All Tasks", value: "all", count: counts.all }, { label: "Contact Tasks", value: "Contact", count: counts.Contact }, { label: "Group Tasks", value: "Group", count: counts.Group }, { label: "Submission Tasks", value: "Submission", count: counts.Submission }]}/></div>
      <div className="portal-list">{visible.map((task) => {
        const Icon = scopeIcon[task.scope] || FileText;
        const assignee = data.participants.find((person) => person.id === task.personId);
        return <article className="portal-row" key={task.id}>
          <div className="portal-row-head"><h3>{task.title}</h3><Pill tone={task.mode === "Automatic" ? "blue" : "neutral"}>{task.mode || "Manual"}</Pill><Pill tone={task.complete ? "success" : "warning"}>{task.complete ? "Complete" : "Open"}</Pill><button className="row-more" onClick={() => setRowMenu(rowMenu === task.id ? null : task.id)}><MoreHorizontal size={20}/></button></div>
          <div className="portal-row-meta"><span>{task.notes || (task.scope === "Submission" ? "Complete for your session" : "Complete your speaker profile")}</span>{assignee ? <span>Assigned to {assignee.name}</span> : null}{task.due ? <span>Due {new Date(task.due).toLocaleString()}</span> : null}<span className="portal-scope"><Icon size={17}/>{task.scope === "Submission" ? "Session" : task.scope}</span></div>
          {rowMenu === task.id ? <div className="portal-row-menu"><button onClick={() => { setDraft({ ...blankTask(), ...task, personIds: task.personId ? [task.personId] : [] }); setDrawer(true); setRowMenu(null); }}><Settings size={16}/>Edit</button><button className="danger" onClick={() => removeTask(task.id)}><Trash2 size={16}/>Delete</button></div> : null}
        </article>;
      })}</div>
    </div>
    <Drawer open={drawer} title={draft.id ? "Edit Task" : "Add Task"} subtitle={draft.id ? "Update this portal assignment" : "Create the same task for one or more portal participants"} onClose={() => setDrawer(false)} footer={<><Button onClick={() => setDrawer(false)}>Cancel</Button><Button variant="primary" disabled={!draft.title.trim() || !selectedCount} onClick={addTask}>{draft.id ? "Save Task" : `Create ${selectedCount || ""} Task${selectedCount === 1 ? "" : "s"}`}</Button></>}>
      <div className="portal-drawer-stack">
        <Field label="Title" required><input value={draft.title} placeholder="e.g. Upload presentation slides" onChange={(event) => setDraft({ ...draft, title: event.target.value })}/></Field>
        {draft.id ? <Field label="Assignee" required><select value={draft.personId || ""} onChange={(event) => setDraft({ ...draft, personId: event.target.value })}><option value="">Select a portal participant...</option>{data.participants.map((person) => <option key={person.id} value={person.id}>{person.name} · {person.email}</option>)}</select></Field> : <Field label={`Assignees (${draft.personIds.length} selected)`} required><div style={{ display: "grid", gap: 8 }}>{data.participants.map((person) => <label key={person.id} style={{ display: "flex", gap: 10, alignItems: "center", minHeight: 44, border: "1px solid #dfe5ed", borderRadius: 8, padding: "8px 12px" }}><input type="checkbox" checked={draft.personIds.includes(person.id)} onChange={() => toggleAssignee(person.id)}/><span><b>{person.name}</b><small style={{ display: "block", color: "#738197" }}>{person.email}</small></span></label>)}</div></Field>}
        <Field label="Due date"><input type="datetime-local" value={draft.due?.slice(0, 16) || ""} onChange={(event) => setDraft({ ...draft, due: event.target.value })}/></Field>
        <Field label="Assignment type" required><TypeCards value={draft.scope} onChange={(scope) => setDraft({ ...draft, scope })}/></Field>
        <Field label="Instructions"><RichEditor value={draft.notes} onChange={(notes) => setDraft({ ...draft, notes })}/></Field>
      </div>
    </Drawer>
  </>;
}

const blankForm = () => ({ id: null, name: "", title: "", type: "Contact", sectionTitle: "Update Your Information", instructions: "Please add or update your information below.", questions: [{ id: "title", label: "Title", type: "Text", required: true, locked: true }], confirmation: true, confirmationBody: "Thank you for submitting your form. Here is a link to your submission." });

export function PortalFormsScreen() {
  const { data, update, persistenceStatus } = useAppStore();
  const forms = data.portalForms || [];
  const [view, setView] = useState("list");
  const [tab, setTab] = useState("all");
  const [addMenu, setAddMenu] = useState(false);
  const [step, setStep] = useState(0);
  const [draft, setDraft] = useState(blankForm);
  const [fieldMenu, setFieldMenu] = useState(false);
  const [fieldSearch, setFieldSearch] = useState("");
  const [saved, setSaved] = useState(false);
  const [saveError,setSaveError]=useState("");
  const counts = { all: forms.length, Contact: forms.filter((form) => form.type === "Contact").length, Group: forms.filter((form) => form.type === "Group").length, Submission: forms.filter((form) => form.type === "Submission").length };
  const visible = forms.filter((form) => tab === "all" || form.type === tab);
  const validSetup = draft.name.trim() && draft.title.trim() && draft.type;
  const beginCreate = () => { setDraft(blankForm()); setStep(0); setView("builder"); setAddMenu(false); };
  const beginEdit = (form) => { setDraft({ ...blankForm(), ...form }); setStep(1); setView("builder"); };
  const save = async(returnToList = false) => {let item={...draft,id:draft.id||`portal-form-${Date.now()}`};setSaveError("");if(persistenceStatus==="d1"){const {id,name,title,type,version,...schema}=item;const result=draft.id?await patchSharedResource("portal-forms",draft.id,draft.version,{name,title,type,schema}):await createSharedResource("portal-forms",{name,title,type,schema});if(!result.ok){setSaveError(result.error==="VERSION_CONFLICT"?"This portal form changed elsewhere. Reload first.":"The shared portal form could not be saved.");return;}item={...item,id:result.item.id,version:result.item.version};}update((state)=>({...state,portalForms:(state.portalForms||[]).some((form)=>form.id===item.id)?(state.portalForms||[]).map((form)=>form.id===item.id?item:form):[...(state.portalForms||[]),item]}));setDraft(item);setSaved(true);setTimeout(()=>setSaved(false),2600);if(returnToList)setView("list");};
  const duplicate = async() => {let item={...draft,id:`portal-form-${Date.now()}`,name:`${draft.name} copy`,version:undefined};setSaveError("");if(persistenceStatus==="d1"){const {id,name,title,type,version,...schema}=item;const result=await createSharedResource("portal-forms",{name,title,type,schema});if(!result.ok){setSaveError("The shared portal form copy could not be created.");return;}item={...item,id:result.item.id,version:result.item.version};}update((state)=>({...state,portalForms:[...(state.portalForms||[]),item]}));setDraft(item);};
  const remove = async() => {if(draft.id&&persistenceStatus==="d1"){const result=await deleteSharedResource("portal-forms",draft.id,draft.version);if(!result.ok){setSaveError("The shared portal form could not be deleted.");return;}}if(draft.id)update((state)=>({...state,portalForms:(state.portalForms||[]).filter((form)=>form.id!==draft.id)}));setView("list");};
  const library = [{ label: "Client Session ID", type: "text" }, { label: "Description", type: "wysiwyg" }, { label: "Format", type: "dropdown" }, { label: "Language", type: "dropdown" }, { label: "Level", type: "dropdown" }, { label: "Tags", type: "dropdown" }].filter((item) => item.label.toLowerCase().includes(fieldSearch.toLowerCase()));
  const addQuestion = (item) => { setDraft({ ...draft, questions: [...draft.questions, { id: `question-${Date.now()}`, label: item.label, type: item.type, required: false, locked: false }] }); setFieldMenu(false); };
  if (view === "builder") return <><style>{PORTAL_STYLES}</style><div className="portal-builder"><header className="portal-builder-head"><div><h1>{draft.id ? "Edit Form" : "Create Form"}</h1>{draft.id ? <p>{draft.name}</p> : null}{saveError?<p style={{color:"#b42318"}}>{saveError}</p>:null}</div><div className="portal-builder-actions">{draft.id ? <><Button icon={Copy} onClick={duplicate}>Duplicate</Button><Button variant="danger" icon={Trash2} onClick={remove}>Delete</Button><Button variant="primary" icon={FileText} onClick={() => save(false)}>Save</Button></> : <Button variant="primary" icon={FileText} disabled={!validSetup} onClick={() => save(false)}>Create</Button>}</div></header><div className="portal-builder-body"><aside className="portal-step-rail"><button className="portal-back" onClick={() => setView("list")}><ArrowLeft size={18} />Back to forms</button><div className="portal-rail-label">Form setup</div>{[["Form Setup", "Name, module, and welcome ...", PanelTop], ["Form Questions", "Questions and section headings...", FileText], ["Settings", "Deadlines, login, reminders, a...", Settings]].map(([title, copy, Icon], index) => <button key={title} className={`portal-step ${step === index ? "current" : ""} ${step > index ? "completed" : ""}`} disabled={index > step && (!validSetup || index > step + 1)} onClick={() => index <= step || validSetup ? setStep(index) : null}><span>{step > index ? <Check size={19} /> : <Icon size={19} />}</span><div><b>{title}</b><small>{copy}</small></div></button>)}</aside><main className="portal-builder-main">
      {step === 0 ? <><div className="portal-builder-title"><h2>Form Setup</h2><p>Give your form an internal name, public title, and select what kind of form you want to build.</p></div><section className="portal-setup-card"><Field label="Name" required><input placeholder="e.g. Speaker Contact Form" value={draft.name} onChange={(event) => setDraft({ ...draft, name: event.target.value })} /></Field><Field label="Title" required><input placeholder="e.g. Add A Contact To Manage Your Portal" value={draft.title} onChange={(event) => setDraft({ ...draft, title: event.target.value })} /></Field></section><section className="portal-builder-section"><h3>Type</h3><TypeCards value={draft.type} onChange={(type) => setDraft({ ...draft, type })} /></section></> : null}
      {step === 1 ? <><div className="portal-builder-title"><h2>Form Questions</h2><p>Add and arrange the fields participants will fill out.</p></div><section className="portal-questions-card"><Field label="Section Title" required><input value={draft.sectionTitle} onChange={(event) => setDraft({ ...draft, sectionTitle: event.target.value })} /></Field><div style={{height:20}} /><Field label="Description & Instructions"><RichEditor value={draft.instructions} onChange={(instructions) => setDraft({ ...draft, instructions })} /></Field></section><section className="question-list-card"><header className="question-list-head"><h3>Form Questions</h3><div className="field-menu-wrap"><Button icon={Plus} onClick={() => setFieldMenu(!fieldMenu)}>Add Field</Button>{fieldMenu ? <div className="field-menu"><button><CirclePlus size={18} />Add Section Element <ChevronRight size={16} style={{marginLeft:"auto"}} /></button><button onClick={() => addQuestion({ label: "New Field", type: "text" })}><CirclePlus size={18} />Create Field</button><label className="field-search"><Search size={18} /><input autoFocus value={fieldSearch} placeholder="Search fields..." onChange={(event) => setFieldSearch(event.target.value)} /></label>{library.map((item) => <button key={item.label} className="field-option" onClick={() => addQuestion(item)}><span>{item.label}</span><span>{item.type}</span></button>)}</div> : null}</div></header><div className="portal-list">{draft.questions.map((question,index) => <div className="portal-form-row" key={question.id}><GripVertical size={18} color="#7b899d" /><div className="question-copy"><b>{question.label}{question.required ? <span style={{color:"#dc2626"}}> *</span> : null}</b><small>{question.type}</small></div><div className="question-actions"><span style={{fontSize:11,color:"#7b899d"}}>Required</span><Toggle checked={question.required} onChange={(required) => setDraft({ ...draft, questions: draft.questions.map((item,i) => i === index ? { ...item, required } : item) })} /><Lock size={18} color="#77859a" /><button className="row-more"><MoreHorizontal size={19} /></button></div></div>)}</div></section></> : null}
      {step === 2 ? <><div className="portal-builder-title"><h2>Form Settings</h2><p>Control confirmations and portal behavior for this form.</p></div><section className="portal-confirm-card"><div className="portal-confirm-head"><div><h3>Send Confirmation Email</h3><p>Submitters will receive an email with a link to access their submission in the portal.</p></div><Toggle checked={draft.confirmation} onChange={(confirmation) => setDraft({ ...draft, confirmation })} /></div><RichEditor value={draft.confirmationBody} onChange={(confirmationBody) => setDraft({ ...draft, confirmationBody })} minHeight={175} /></section></> : null}
    </main></div><footer className="portal-builder-footer"><Button disabled={step === 0} onClick={() => setStep(Math.max(0, step - 1))}>Back</Button>{!validSetup ? <p>Complete all required fields on this step to continue.</p> : null}{step < 2 ? <Button variant="primary" disabled={!validSetup || (step === 1 && !draft.sectionTitle)} onClick={() => setStep(step + 1)}>Next</Button> : <Button variant="primary" onClick={() => save(true)}>Save Form</Button>}</footer></div>{saved ? <div className="portal-success-toast"><div><b>Saved successfully</b><span>Your changes have been saved.</span></div><Button onClick={() => setView("list")}>View All Forms</Button></div> : null}</>;
  return <><style>{PORTAL_STYLES}</style><div className="portal-page"><PageHeader icon={PanelTop} title="Forms" subtitle="Create forms that can be assigned to your portals to collect information" actions={<SplitButton menuOpen={addMenu} onMenu={() => setAddMenu(!addMenu)} onClick={beginCreate} items={[{ label: "Add Form", icon: Plus, onClick: beginCreate }, { label: "Copy from...", icon: Copy, onClick: () => forms[0] && beginEdit({ ...forms[0], id:null, name:`${forms[0].name} copy` }) }]} />} /><div className="portal-tabs"><Tabs value={tab} onChange={setTab} items={[{ label:"All Forms",value:"all",count:counts.all },{ label:"Contact Forms",value:"Contact",count:counts.Contact },{ label:"Group Forms",value:"Group",count:counts.Group },{ label:"Submission Forms",value:"Submission",count:counts.Submission }]} /></div>{visible.length ? <div className="portal-list">{visible.map((form) => <button key={form.id} className="portal-form-card" onClick={() => beginEdit(form)}><span className="resource-card-icon"><PanelTop size={22} /></span><span className="portal-form-copy"><b>{form.name}</b><span>{form.title}</span></span><span className="portal-form-tags"><Pill tone="blue">{form.type}</Pill><ChevronRight size={18} /></span></button>)}</div> : <EmptyState className="portal-empty" icon={PanelTop} title="No forms yet" description="Create a form to collect information from participants" />}</div></>;
}

function LegacyFileRequestsScreen() {
  const { data, update, persistenceStatus } = useAppStore();
  const requests = data.fileRequests || [];
  const [tab, setTab] = useState("all");
  const [menu, setMenu] = useState(false);
  const [drawer, setDrawer] = useState(false);
  const [rowMenu, setRowMenu] = useState(null);
  const [saveError, setSaveError] = useState("");
  const emptyDraft = { title:"", type:"Contact", instructions:"", assigneePersonId:"", submissionId:"", dueAt:"", status:"open" };
  const [draft, setDraft] = useState(emptyDraft);
  const counts = { all:requests.length, Contact:requests.filter((item)=>item.type==="Contact").length, Group:requests.filter((item)=>item.type==="Group").length, Submission:requests.filter((item)=>item.type==="Submission").length };
  const visible = requests.filter((item) => tab === "all" || item.type === tab);
  const targetIsValid = draft.type === "Contact" ? Boolean(draft.assigneePersonId) : draft.type === "Submission" ? Boolean(draft.submissionId) : Boolean(draft.assigneePersonId || draft.submissionId);
  const requestPayload = (item) => ({title:item.title,type:item.type,instructions:item.instructions||null,assigneePersonId:item.assigneePersonId||null,submissionId:item.submissionId||null,dueAt:item.dueAt||null,status:item.status||"open"});
  const create = async () => {let item={id:draft.id||`request-${Date.now()}`,...draft,files:draft.files||[]};setSaveError("");if(persistenceStatus==="d1"){const result=draft.id?await patchSharedResource("file-requests",draft.id,draft.version,requestPayload(draft)):await createSharedResource("file-requests",requestPayload(draft));if(!result.ok){setSaveError(result.error==="VERSION_CONFLICT"?"This file request changed elsewhere. Reload first.":"The shared file request could not be saved.");return;}item={...item,...result.item,id:result.item.id,version:result.item.version};}update((state)=>({...state,fileRequests:(state.fileRequests||[]).some((request)=>request.id===item.id)?(state.fileRequests||[]).map((request)=>request.id===item.id?item:request):[...(state.fileRequests||[]),item]}));setDrawer(false);setDraft(emptyDraft);};
  const copyRequest=async()=>{const source=requests[0];if(!source){setMenu(false);return;}let item={...source,id:`request-${Date.now()}`,title:`${source.title} copy`,version:undefined,files:[]};setSaveError("");if(persistenceStatus==="d1"){const result=await createSharedResource("file-requests",requestPayload(item));if(!result.ok){setSaveError("The shared file request copy could not be created.");return;}item={...item,...result.item,id:result.item.id,version:result.item.version};}update((state)=>({...state,fileRequests:[...(state.fileRequests||[]),item]}));setMenu(false);};
  const removeRequest=async(item)=>{setSaveError("");if(persistenceStatus==="d1"){const result=await deleteSharedResource("file-requests",item.id,item.version);if(!result.ok){setSaveError("The shared file request could not be deleted.");return;}}update((state)=>({...state,fileRequests:(state.fileRequests||[]).filter((request)=>request.id!==item.id)}));setRowMenu(null);};
  return <><style>{PORTAL_STYLES}</style><div className="portal-page"><PageHeader icon={FileInput} title="File Requests" subtitle="Collect files (e.g. documents, contracts) from your portals. Uploaded files are stored here for download or export — they are not attached to a submission or contact record." actions={<SplitButton menuOpen={menu} onMenu={() => setMenu(!menu)} onClick={() => setDrawer(true)} items={[{label:"Add File Request",icon:Plus,onClick:()=>{setDrawer(true);setMenu(false);}},{label:"Copy from...",icon:Copy,onClick:copyRequest}]} />} />{saveError?<div className="portal-info" style={{marginBottom:16}}><Info size={18}/><p>{saveError}</p></div>:null}<div className="portal-tabs"><Tabs value={tab} onChange={setTab} items={[{label:"All Requests",value:"all",count:counts.all},{label:"Contact Requests",value:"Contact",count:counts.Contact},{label:"Group Requests",value:"Group",count:counts.Group},{label:"Submission Requests",value:"Submission",count:counts.Submission}]} /></div>{visible.length ? <div className="portal-list">{visible.map((item) => <article className="portal-row" key={item.id}><div className="portal-row-head"><h3>{item.title}</h3><Pill tone="blue">{item.type}</Pill><button className="row-more" onClick={()=>setRowMenu(rowMenu===item.id?null:item.id)}><MoreHorizontal size={20}/></button></div><div className="portal-row-meta"><FileInput size={17}/><span>{item.instructions || "Portal file request"}</span><span style={{marginLeft:"auto"}}>{item.files?.length || 0} files</span></div>{rowMenu===item.id?<div className="portal-row-menu"><button onClick={()=>{setDraft({...item});setDrawer(true);setRowMenu(null);}}><Settings size={16}/>Edit</button><button className="danger" onClick={()=>removeRequest(item)}><Trash2 size={16}/>Delete</button></div>:null}</article>)}</div> : <EmptyState icon={FileInput} title="No file requests yet" description="Create a file request to collect documents from participants" />}</div><Drawer open={drawer} wide title={draft.id?"Edit File Request":"Add File Request"} subtitle="Create a file request for participants" onClose={()=>setDrawer(false)} footer={<><Button onClick={()=>setDrawer(false)}>Cancel</Button><Button variant="primary" disabled={!draft.title || !draft.type} onClick={create}>{draft.id?"Save File Request":"Create File Request"}</Button></>}><div className="portal-drawer-stack"><div className="portal-info"><Info size={21}/><div><h4>Files are stored, not attached</h4><p>Uploaded files live on this File Request and can be downloaded or exported. They are not attached to the contact, group, or session record.</p></div></div><Field label="Title"><input placeholder="e.g. Upload Presentation Slides" value={draft.title} onChange={(event)=>setDraft({...draft,title:event.target.value})}/></Field><Field label="Type" required><TypeCards value={draft.type} onChange={(type)=>setDraft({...draft,type})}/></Field><Field label="Instructions"><RichEditor value={draft.instructions} onChange={(instructions)=>setDraft({...draft,instructions})}/></Field></div></Drawer></>;
}

export function FileRequestsScreen() {
  const { data, update, persistenceStatus } = useAppStore();
  const requests = data.fileRequests || [];
  const emptyDraft = { title:"", type:"Contact", instructions:"", assigneePersonId:"", submissionId:"", dueAt:"", status:"open" };
  const [tab,setTab]=useState("all");
  const [drawer,setDrawer]=useState(false);
  const [rowMenu,setRowMenu]=useState(null);
  const [saveError,setSaveError]=useState("");
  const [draft,setDraft]=useState(emptyDraft);
  const visible=requests.filter((item)=>tab==="all"||item.type===tab);
  const counts={all:requests.length,Contact:requests.filter((item)=>item.type==="Contact").length,Group:requests.filter((item)=>item.type==="Group").length,Submission:requests.filter((item)=>item.type==="Submission").length};
  const targetIsValid=draft.type==="Submission"?Boolean(draft.submissionId):Boolean(draft.assigneePersonId);
  const requestPayload=(item)=>({title:item.title,type:item.type,instructions:item.instructions||null,assigneePersonId:item.assigneePersonId||null,submissionId:item.submissionId||null,dueAt:item.dueAt||null,status:item.status||"open"});
  const save=async()=>{let item={id:draft.id||`request-${Date.now()}`,...draft,files:draft.files||[]};setSaveError("");if(persistenceStatus==="d1"){const result=draft.id?await patchSharedResource("file-requests",draft.id,draft.version,requestPayload(draft)):await createSharedResource("file-requests",requestPayload(draft));if(!result.ok){setSaveError(result.error==="VERSION_CONFLICT"?"This file request changed elsewhere. Reload first.":"The shared file request could not be saved.");return;}item={...item,...result.item};}update((state)=>({...state,fileRequests:(state.fileRequests||[]).some((request)=>request.id===item.id)?(state.fileRequests||[]).map((request)=>request.id===item.id?item:request):[...(state.fileRequests||[]),item]}));setDrawer(false);setDraft(emptyDraft);};
  const remove=async(item)=>{setSaveError("");if(persistenceStatus==="d1"){const result=await deleteSharedResource("file-requests",item.id,item.version);if(!result.ok){setSaveError("The shared file request could not be deleted.");return;}}update((state)=>({...state,fileRequests:(state.fileRequests||[]).filter((request)=>request.id!==item.id)}));setRowMenu(null);};
  const targetLabel=(item)=>item.assigneePersonId?(data.participants.find((person)=>person.id===item.assigneePersonId)?.name||"Assigned participant"):(data.abstracts.find((submission)=>submission.id===item.submissionId)?.title||"Assigned submission");
  const fileCount=(item)=>(data.portalFiles||[]).filter((file)=>file.fileRequestId===item.id).length;
  const formatDueDate=(value)=>{
    const dateOnly=String(value||"").match(/^(\d{4})-(\d{2})-(\d{2})/);
    if(!dateOnly)return "";
    return new Intl.DateTimeFormat("en-US",{month:"short",day:"numeric",year:"numeric",timeZone:"UTC"}).format(new Date(`${dateOnly[1]}-${dateOnly[2]}-${dateOnly[3]}T12:00:00Z`));
  };
  return <>
    <style>{PORTAL_STYLES}</style>
    <div className="portal-page">
      <PageHeader icon={FileInput} title="File Requests" subtitle="Collect a specific file from an assigned participant or submission. Access follows that assignment." actions={<Button variant="primary" icon={Plus} onClick={()=>{setDraft(emptyDraft);setDrawer(true);}}>Add File Request</Button>} />
      {saveError?<div className="portal-info" style={{marginBottom:16}}><Info size={18}/><p>{saveError}</p></div>:null}
      <div className="portal-tabs"><Tabs value={tab} onChange={setTab} items={[{label:"All Requests",value:"all",count:counts.all},{label:"Contact Requests",value:"Contact",count:counts.Contact},{label:"Group Requests",value:"Group",count:counts.Group},{label:"Submission Requests",value:"Submission",count:counts.Submission}]}/></div>
      {visible.length?<div className="portal-list">{visible.map((item)=><article className="portal-row" key={item.id}>
        <div className="portal-row-head"><h3>{item.title}</h3><Pill tone="blue">{item.type}</Pill><button className="row-more" onClick={()=>setRowMenu(rowMenu===item.id?null:item.id)}><MoreHorizontal size={20}/></button></div>
        <div className="portal-row-meta"><FileInput size={17}/><span>{targetLabel(item)}</span>{item.dueAt?<span>Due {formatDueDate(item.dueAt)}</span>:null}<span style={{marginLeft:"auto"}}>{fileCount(item)} file{fileCount(item)===1?"":"s"}</span></div>
        {rowMenu===item.id?<div className="portal-row-menu"><button onClick={()=>{setDraft({...emptyDraft,...item});setDrawer(true);setRowMenu(null);}}><Settings size={16}/>Edit</button><button className="danger" onClick={()=>remove(item)}><Trash2 size={16}/>Delete</button></div>:null}
      </article>)}</div>:<EmptyState icon={FileInput} title="No file requests yet" description="Create a request and assign it to one participant or submission"/>}
    </div>
    <Drawer open={drawer} wide title={draft.id?"Edit File Request":"Add File Request"} subtitle="Only the assigned participant or submission speakers can access this request" onClose={()=>setDrawer(false)} footer={<><Button onClick={()=>setDrawer(false)}>Cancel</Button><Button variant="primary" disabled={!draft.title||!targetIsValid} onClick={save}>{draft.id?"Save File Request":"Create File Request"}</Button></>}>
      <div className="portal-drawer-stack">
        <div className="portal-info"><Info size={21}/><div><h4>Private by assignment</h4><p>Access is checked again when the participant uploads a file. Other portal users cannot list or complete this request.</p></div></div>
        <Field label="Title" required><input placeholder="e.g. Upload final presentation" value={draft.title} onChange={(event)=>setDraft({...draft,title:event.target.value})}/></Field>
        <Field label="Type" required><TypeCards value={draft.type} onChange={(type)=>setDraft({...draft,type,assigneePersonId:type==="Submission"?"":draft.assigneePersonId,submissionId:type==="Submission"?draft.submissionId:""})}/></Field>
        {draft.type==="Submission"?<Field label="Submission" required><select value={draft.submissionId} onChange={(event)=>setDraft({...draft,submissionId:event.target.value})}><option value="">Select a submission...</option>{data.abstracts.map((submission)=><option key={submission.id} value={submission.id}>{submission.title}</option>)}</select></Field>:<Field label="Participant" required><select value={draft.assigneePersonId} onChange={(event)=>setDraft({...draft,assigneePersonId:event.target.value})}><option value="">Select a participant...</option>{data.participants.map((person)=><option key={person.id} value={person.id}>{person.name} · {person.email}</option>)}</select></Field>}
        <Field label="Due date"><input type="datetime-local" value={draft.dueAt?.slice(0,16)||""} onChange={(event)=>setDraft({...draft,dueAt:event.target.value})}/></Field>
        <Field label="Instructions"><RichEditor value={draft.instructions} onChange={(instructions)=>setDraft({...draft,instructions})}/></Field>
      </div>
    </Drawer>
  </>;
  /*
  return <><style>{PORTAL_STYLES}</style><div className="portal-page"><PageHeader icon={FileInput} title="File Requests" subtitle="Collect a specific file from an assigned participant or submission. Access follows that assignment." actions={<Button variant="primary" icon={Plus} onClick={()=>{setDraft(emptyDraft);setDrawer(true);}}>Add File Request</Button>}/>{saveError?<div className="portal-info" style={{marginBottom:16}}><Info size={18}/><p>{saveError}</p></div>:null}<div className="portal-tabs"><Tabs value={tab} onChange={setTab} items={[{label:"All Requests",value:"all",count:counts.all},{label:"Contact Requests",value:"Contact",count:counts.Contact},{label:"Group Requests",value:"Group",count:counts.Group},{label:"Submission Requests",value:"Submission",count:counts.Submission}]}/></div>{visible.length?<div className="portal-list">{visible.map((item)=><article className="portal-row" key={item.id}><div className="portal-row-head"><h3>{item.title}</h3><Pill tone="blue">{item.type}</Pill><button className="row-more" onClick={()=>setRowMenu(rowMenu===item.id?null:item.id)}><MoreHorizontal size={20}/></button></div><div className="portal-row-meta"><FileInput size={17}/><span>{targetLabel(item)}</span>{item.dueAt?<span>Due {new Date(item.dueAt).toLocaleDateString()}</span>:null}<span style={{marginLeft:"auto"}}>{fileCount(item)} files</span></div>{rowMenu===item.id?<div className="portal-row-menu"><button onClick={()=>{setDraft({...emptyDraft,...item});setDrawer(true);setRowMenu(null);}}><Settings size={16}/>Edit</button><button className="danger" onClick={()=>remove(item)}><Trash2 size={16}/>Delete</button></div>:null}</article>)}</div>:<EmptyState icon={FileInput} title="No file requests yet" description="Create a request and assign it to one participant or submission"/></div><Drawer open={drawer} wide title={draft.id?"Edit File Request":"Add File Request"} subtitle="Only the assigned participant or submission speakers can access this request" onClose={()=>setDrawer(false)} footer={<><Button onClick={()=>setDrawer(false)}>Cancel</Button><Button variant="primary" disabled={!draft.title||!targetIsValid} onClick={save}>{draft.id?"Save File Request":"Create File Request"}</Button></>}><div className="portal-drawer-stack"><div className="portal-info"><Info size={21}/><div><h4>Private by assignment</h4><p>Access is checked again when the participant uploads a file. Other portal users cannot list or complete this request.</p></div></div><Field label="Title" required><input placeholder="e.g. Upload final presentation" value={draft.title} onChange={(event)=>setDraft({...draft,title:event.target.value})}/></Field><Field label="Type" required><TypeCards value={draft.type} onChange={(type)=>setDraft({...draft,type,assigneePersonId:type==="Submission"?"":draft.assigneePersonId,submissionId:type==="Submission"?draft.submissionId:""})}/></Field>{draft.type==="Submission"?<Field label="Submission" required><select value={draft.submissionId} onChange={(event)=>setDraft({...draft,submissionId:event.target.value})}><option value="">Select a submission...</option>{data.abstracts.map((submission)=><option key={submission.id} value={submission.id}>{submission.title}</option>)}</select></Field>:<Field label="Participant" required><select value={draft.assigneePersonId} onChange={(event)=>setDraft({...draft,assigneePersonId:event.target.value})}><option value="">Select a participant...</option>{data.participants.map((person)=><option key={person.id} value={person.id}>{person.name} · {person.email}</option>)}</select></Field>}<Field label="Due date"><input type="datetime-local" value={draft.dueAt?.slice(0,16)||""} onChange={(event)=>setDraft({...draft,dueAt:event.target.value})}/></Field><Field label="Instructions"><RichEditor value={draft.instructions} onChange={(instructions)=>setDraft({...draft,instructions})}/></Field></div></Drawer></>;
  */
}

export function ResourcesScreen() {
  const { data, update, persistenceStatus } = useAppStore();
  const resources = data.resources || [];
  const [drawer,setDrawer]=useState(false);
  const [draft,setDraft]=useState({title:"",kind:"Link",url:"",description:"",audience:"All portal users"});
  const [saveError,setSaveError]=useState("");
  const emptyResource=()=>({title:"",kind:"Link",url:"",description:"",audience:"All portal users"});
  const openCreate=()=>{setDraft(emptyResource());setSaveError("");setDrawer(true);};
  const openEdit=(item)=>{setDraft({...emptyResource(),...item,description:item.description||item.content||""});setSaveError("");setDrawer(true);};
  const save=async()=>{let item={id:draft.id||`resource-${Date.now()}`,...draft};setSaveError("");if(persistenceStatus==="d1"){const payload={title:draft.title,kind:draft.kind,url:draft.url||null,content:draft.description||null,audience:draft.audience};const result=draft.id?await patchSharedResource("resources",draft.id,draft.version,payload):await createSharedResource("resources",payload);if(!result.ok){setSaveError(result.error==="VERSION_CONFLICT"?"This resource changed elsewhere. Reload first.":"The shared resource could not be saved.");return;}item={...item,id:result.item.id,version:result.item.version};}update((state)=>({...state,resources:(state.resources||[]).some((resource)=>resource.id===item.id)?(state.resources||[]).map((resource)=>resource.id===item.id?item:resource):[...(state.resources||[]),item]}));setDrawer(false);setDraft(emptyResource());};
  return <><style>{PORTAL_STYLES}</style><div className="portal-page"><PageHeader icon={Globe2} title="Resources" subtitle="Share guides, links, and event information with your portal participants" actions={<Button variant="primary" icon={Plus} onClick={openCreate}>Add Resource</Button>} />{saveError?<div className="portal-info" style={{marginBottom:16}}><Info size={18}/><p>{saveError}</p></div>:null}{resources.length?<div className="resource-grid">{resources.map((item)=><article className="resource-card" key={item.id}><span className="resource-card-icon">{item.kind==="Link"?<Globe2 size={22}/>:<FileText size={22}/>}</span><h3>{item.title}</h3><p>{item.description||item.content||item.url||"Portal resource"}</p><footer><Pill tone="blue">{item.audience}</Pill><button className="row-more" aria-label={`Edit ${item.title}`} onClick={()=>openEdit(item)}><MoreHorizontal size={19}/></button></footer></article>)}</div>:<EmptyState icon={Globe2} title="No resources yet" description="Create a resource to help participants prepare for your event" />}</div><Drawer open={drawer} title={draft.id?"Edit Resource":"Add Resource"} subtitle="Publish useful information to the portal" onClose={()=>setDrawer(false)} footer={<><Button onClick={()=>setDrawer(false)}>Cancel</Button><Button variant="primary" disabled={!draft.title} onClick={save}>{draft.id?"Save Resource":"Create Resource"}</Button></>}><div className="portal-drawer-stack"><Field label="Title" required><input value={draft.title} onChange={(event)=>setDraft({...draft,title:event.target.value})}/></Field><Field label="Type"><select value={draft.kind} onChange={(event)=>setDraft({...draft,kind:event.target.value})}><option>Link</option><option>Article</option><option>HTML Embed</option></select></Field>{draft.kind==="Link"?<Field label="URL"><input value={draft.url} placeholder="https://" onChange={(event)=>setDraft({...draft,url:event.target.value})}/></Field>:null}<Field label={draft.kind==="HTML Embed"?"Sandboxed HTML":"Description"}><RichEditor value={draft.description} onChange={(description)=>setDraft({...draft,description})}/></Field><Field label="Audience"><select value={draft.audience} onChange={(event)=>setDraft({...draft,audience:event.target.value})}><option>All portal users</option><option>Contacts</option><option>Accepted speakers</option></select></Field></div></Drawer></>;
}

export function PortalFilesScreen() {
  const { data, update, persistenceStatus } = useAppStore();
  const files=data.portalFiles||[];
  const [drawer,setDrawer]=useState(false);
  const [picked,setPicked]=useState(null);
  const [ownerPersonId,setOwnerPersonId]=useState("");
  const [saveError,setSaveError]=useState("");
  const add=async()=>{if(!picked)return;let item={id:`file-${Date.now()}`,name:picked.name,size:picked.size,type:picked.type||"Document",uploaded:new Date().toLocaleDateString(),personId:ownerPersonId};setSaveError("");if(persistenceStatus==="d1"){const result=await uploadSharedFile(picked,{kind:"Portal library",ownerPersonId});if(!result.ok){setSaveError("The private file could not be uploaded.");return;}item={...item,id:result.item.id,version:result.item.version,status:result.item.status,downloadUrl:`/api/files/${encodeURIComponent(result.item.id)}/content`};}update((state)=>({...state,portalFiles:[...(state.portalFiles||[]),item]}));setPicked(null);setOwnerPersonId("");setDrawer(false);};
  const sharedStorageUnavailable=persistenceStatus==="d1"&&!data.objectStorageAvailable;
  return <><style>{PORTAL_STYLES}</style><div className="portal-page"><PageHeader icon={FolderOpen} title="Files" subtitle="Manage files available across your participant portals" actions={<Button variant="primary" icon={Upload} disabled={sharedStorageUnavailable} onClick={()=>setDrawer(true)}>Upload File</Button>} />{sharedStorageUnavailable?<div className="portal-info" style={{marginBottom:18}}><Info size={20}/><div><h4>Private file storage is not enabled</h4><p>This shared preview will not pretend a browser-selected file was uploaded. The controls activate only after the approved private object-store binding is present.</p></div></div>:null}{saveError?<div className="portal-info" style={{marginBottom:18}}><Info size={18}/><p>{saveError}</p></div>:null}{files.length?<table className="file-table"><thead><tr><th>Name</th><th>Speaker</th><th>Type</th><th>Version</th><th>Size</th><th>Uploaded</th><th></th></tr></thead><tbody>{files.map((item)=>{const owner=data.participants.find((person)=>person.id===item.personId);return <tr key={item.id}><td>{item.name}</td><td>{owner?.name||"Event team"}</td><td>{item.type}</td><td>v{item.version||1}</td><td>{formatBytes(item.size)}</td><td>{item.uploaded}</td><td>{item.downloadUrl?<a href={item.downloadUrl} aria-label={`Download ${item.name}`}><Download size={17}/></a>:null}</td></tr>;})}</tbody></table>:<EmptyState icon={FolderOpen} title="No portal files yet" description={sharedStorageUnavailable?"Private object storage is required before files can be uploaded":"Upload event documents and resources for your portal participants"} />}</div><Drawer open={drawer&&!sharedStorageUnavailable} title="Upload File" subtitle="Add a private file to a participant portal" onClose={()=>setDrawer(false)} footer={<><Button onClick={()=>setDrawer(false)}>Cancel</Button><Button variant="primary" disabled={!picked||(persistenceStatus==="d1"&&!ownerPersonId)} onClick={add}>Upload File</Button></>}><div className="portal-drawer-stack">{persistenceStatus==="d1"?<Field label="Portal participant" required><select value={ownerPersonId} onChange={(event)=>setOwnerPersonId(event.target.value)}><option value="">Select a participant...</option>{data.participants.map((person)=><option key={person.id} value={person.id}>{person.name} · {person.email}</option>)}</select></Field>:null}<div className="file-drop"><Upload size={34}/><b>{picked?picked.name:"Choose a file to upload"}</b><input type="file" onChange={(event)=>setPicked(event.target.files?.[0]||null)}/></div></div></Drawer></>;
}

function formatBytes(bytes=0){if(!bytes)return "0 KB";if(bytes<1024*1024)return `${Math.max(1,Math.round(bytes/1024))} KB`;return `${(bytes/1024/1024).toFixed(1)} MB`;}
